begin;

-- ═══════════════════════════════════════════════════════════════════════════
-- Trust & social proof — every public claim is backed by data staff control.
--   trust_stats      verified stats; a source note is REQUIRED to publish
--   testimonials     parent videos / letters / notebooks; consent REQUIRED to publish
--   recent_activity  anonymised feed of real recent bookings (powers the TrustTicker)
--   leads.promo_code incentive claimed in the app (e.g. exit-intent e-book)
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── trust_stats ────────────────────────────────────────────────────────────
create table public.trust_stats (
  id            uuid primary key default gen_random_uuid(),
  icon          text not null,                    -- emoji, e.g. '⭐'
  headline      text,                             -- '98%' (null for qualitative claims)
  label         text not null,                    -- 'học sinh cải thiện nét chữ sau 1 tháng'
  source_note   text not null default '',         -- 'Đánh giá đầu vào/ra của 126 HS, T6–T9/2026'
  measured_on   date,
  sort_order    smallint not null default 0,
  is_published  boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  -- A stat cannot go live without saying where it comes from.
  constraint trust_stats_source_required check (not is_published or char_length(btrim(source_note)) >= 10)
);

create trigger trust_stats_updated_at before update on public.trust_stats
  for each row execute function public.set_updated_at();

-- ─── testimonials ───────────────────────────────────────────────────────────
create table public.testimonials (
  id                 uuid primary key default gen_random_uuid(),
  kind               text not null check (kind in ('VIDEO', 'LETTER', 'NOTEBOOK')),
  parent_label       text not null,                       -- 'Mẹ bé Gia Bảo' — as approved by the parent
  course_code        text not null references public.categories (code) on update cascade,
  branch_location    text references public.branches (code) on update cascade,
  quote              text not null default '',
  media_url          text not null check (media_url ~ '^https://'),
  thumbnail_url      text check (thumbnail_url is null or thumbnail_url ~ '^https://'),
  duration_sec       int check (duration_sec is null or duration_sec > 0),
  recorded_on        date,
  -- Written consent from the parent to publish (name, child's work, face/voice).
  consent_confirmed  boolean not null default false,
  is_published       boolean not null default false,
  sort_order         smallint not null default 0,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint testimonials_consent_required check (not is_published or consent_confirmed),
  constraint testimonials_video_thumb check (kind <> 'VIDEO' or thumbnail_url is not null)
);

create index testimonials_public_idx on public.testimonials (kind, sort_order, created_at desc)
  where is_published and consent_confirmed;

create trigger testimonials_updated_at before update on public.testimonials
  for each row execute function public.set_updated_at();

-- ─── RLS ────────────────────────────────────────────────────────────────────
alter table public.trust_stats  enable row level security;
alter table public.testimonials enable row level security;

create policy "public read published stats"
  on public.trust_stats for select to anon, authenticated
  using (is_published);

create policy "public read consented testimonials"
  on public.testimonials for select to anon, authenticated
  using (is_published and consent_confirmed);

create policy "staff manage stats"
  on public.trust_stats for all to authenticated
  using (public.is_staff()) with check (public.is_staff());

create policy "staff manage testimonials"
  on public.testimonials for all to authenticated
  using (public.is_staff()) with check (public.is_staff());

-- ─── leads.promo_code ───────────────────────────────────────────────────────
alter table public.leads
  add column promo_code text check (promo_code is null or promo_code in ('EBOOK_VAO_LOP_1'));

grant insert (promo_code) on public.leads to anon;

-- ─── recent_activity: anonymised real bookings ──────────────────────────────
-- SECURITY DEFINER so the public can see *that* bookings happen without reading leads.
-- Exposes only: masked label ("Phụ huynh T."), course, branch, time. No ids, phones or child data.
create or replace function public.recent_activity(p_limit int default 12)
returns table (
  actor_label  text,
  course_code  text,
  course_name  text,
  branch_code  text,
  branch_name  text,
  created_at   timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select
    'Phụ huynh ' || upper(left(
      (string_to_array(btrim(l.parent_name), ' '))[array_length(string_to_array(btrim(l.parent_name), ' '), 1)],
      1)) || '.' as actor_label,
    l.course_code,
    c.name,
    l.branch_location,
    b.name,
    -- Round to 5 minutes: enough for "x phút trước", not enough to pinpoint someone.
    date_trunc('hour', l.created_at) + floor(extract(minute from l.created_at) / 5) * interval '5 minutes'
  from public.leads l
  join public.categories c on c.code = l.course_code
  join public.branches b on b.code = l.branch_location
  where l.created_at > now() - interval '7 days'
  order by l.created_at desc
  limit least(greatest(coalesce(p_limit, 12), 1), 30);
$$;

revoke all on function public.recent_activity(int) from public;
grant execute on function public.recent_activity(int) to anon, authenticated;

-- ─── submit_lead: accept promo_code ─────────────────────────────────────────
-- Re-declared with the promo field; body otherwise identical to 20261111090200_functions.sql.
create or replace function public.submit_lead(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id           uuid := coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid());
  v_phone        text := regexp_replace(coalesce(p ->> 'phone_number', ''), '[\s.()-]', '', 'g');
  v_parent       text := btrim(coalesce(p ->> 'parent_name', ''));
  v_student      text := btrim(coalesce(p ->> 'student_name', ''));
  v_age          int;
  v_course       text := p ->> 'course_code';
  v_branch       text := p ->> 'branch_location';
  v_promo        text := nullif(p ->> 'promo_code', '');
  v_date         date;
  v_existing     public.leads;
  v_row          public.leads;
  v_recent_count int;
begin
  if v_phone like '+84%' then
    v_phone := '0' || substr(v_phone, 4);
  end if;

  if v_phone !~ '^0[35789][0-9]{8}$' then
    raise exception 'Số điện thoại không hợp lệ' using hint = 'VALIDATION:phone_number';
  end if;
  if char_length(v_parent) not between 2 and 60 or v_parent ~ '[0-9]' then
    raise exception 'Họ tên phụ huynh không hợp lệ' using hint = 'VALIDATION:parent_name';
  end if;
  if char_length(v_student) not between 2 and 60 or v_student ~ '[0-9]' then
    raise exception 'Họ tên của bé không hợp lệ' using hint = 'VALIDATION:student_name';
  end if;
  begin
    v_age := (p ->> 'student_age')::int;
  exception when others then
    v_age := null;
  end;
  if v_age is null or v_age not between 3 and 12 then
    raise exception 'Tuổi của bé không hợp lệ' using hint = 'VALIDATION:student_age';
  end if;
  if not exists (select 1 from public.categories where code = v_course) then
    raise exception 'Khóa học không tồn tại' using hint = 'VALIDATION:course_code';
  end if;
  if not exists (select 1 from public.branches where code = v_branch) then
    raise exception 'Cơ sở không tồn tại' using hint = 'VALIDATION:branch_location';
  end if;
  if v_promo is not null and v_promo not in ('EBOOK_VAO_LOP_1') then
    raise exception 'Mã ưu đãi không hợp lệ' using hint = 'VALIDATION:promo_code';
  end if;
  if p ? 'preferred_date' and nullif(p ->> 'preferred_date', '') is not null then
    v_date := (p ->> 'preferred_date')::date;
    if v_date < current_date or v_date > current_date + 60 then
      raise exception 'Ngày học thử không hợp lệ' using hint = 'VALIDATION:preferred_date';
    end if;
  end if;

  select * into v_existing from public.leads where id = v_id;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  select * into v_existing
  from public.leads
  where phone_number = v_phone
    and course_code = v_course
    and lower(student_name) = lower(v_student)
    and created_at > now() - interval '30 minutes'
  order by created_at desc
  limit 1;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  select count(*) into v_recent_count
  from public.leads
  where phone_number = v_phone and created_at > now() - interval '24 hours';
  if v_recent_count >= 5 then
    raise exception 'Số điện thoại này đã đăng ký nhiều lần hôm nay' using hint = 'RATE_LIMITED';
  end if;

  insert into public.leads (
    id, parent_name, phone_number, student_name, student_age, course_code, branch_location,
    quiz_summary, preferred_date, preferred_slot, source, zalo_user_id, quiz_answers, promo_code
  ) values (
    v_id, v_parent, v_phone, v_student, v_age, v_course, v_branch,
    p -> 'quiz_summary',
    v_date,
    nullif(p ->> 'preferred_slot', ''),
    coalesce(nullif(p ->> 'source', ''), 'DIRECT'),
    nullif(p ->> 'zalo_user_id', ''),
    p -> 'quiz_answers',
    v_promo
  )
  returning * into v_row;

  return jsonb_build_object('id', v_row.id, 'code', v_row.code,
                            'created_at', v_row.created_at, 'duplicate', false);
end;
$$;

commit;
